    public Presence Inspect(Identity id){if(Unknown)return Presence.Unknown;if(Reuse||RiderReuse&&id.Handle==11)return Presence.Reused;Identity found;return !Entities.TryGetValue(id.Handle,out found)?Presence.Absent:found.Same(id)?Presence.Present:Presence.Reused;}
    public bool Persistent(Identity id){return IsPersistent;}
    private void Guard(Identity id){if(Inspect(id)!=Presence.Present||id.Model!=Controller.BatiModel)throw new Exception("unowned tune");}
    public int? KitBefore=65535,KitAfter=207,KitCount=1;public int? RequestedKit;public bool InstallerFailure,BeforeGetterFailure,AfterGetterFailure,KitCountFailure,AfterGetterOwnershipLoss;private bool installed;
    public void InstallKit(Identity id,int selection){Guard(id);RequestedKit=selection;Mutations++;if(InstallerFailure)throw new InvalidOperationException("private paths must not be copied from exceptions");installed=true;}
    public bool KitReadback=true;
    public int? ReadKit(Identity id){Guard(id);if(!installed&&BeforeGetterFailure||installed&&AfterGetterFailure)throw new InvalidOperationException("private paths must not be copied from exceptions");if(installed&&AfterGetterOwnershipLoss)Unknown=true;return installed?(KitReadback?KitAfter:65535):KitBefore;}
    public int? AvailableKits(Identity id){Guard(id);if(KitCountFailure)throw new InvalidOperationException("private diagnostic");return KitCount;}
    public int ModCount(Identity id,int c){Guard(id);return Counts[c];}
    public void SetMod(Identity id,int c,int index){Guard(id);if(index<0||index>=Counts[c])throw new Exception("invalid index");Applied[c]=index;Mutations++;if(TuningFailure||c==ThrowSetCategory)throw new Exception("partial tuning failure");}
    public int ReadMod(Identity id,int c){return Readback&&c!=MismatchedCategory?Applied[c]:-1;}
    public Capability TurboSupport(Identity id){return TurboCapability;}
    public void EnableTurbo(Identity id){Guard(id);Turbo=true;Mutations++;}
    public bool ReadTurbo(Identity id){return Turbo&&TurboRead;}
    public bool Mounted(Identity rider,Identity bike){return true;}
    public void Drive(Identity r,Identity b,MarkerPoint target,double speed){if(!r.Same(Entities[11])||!b.Same(Entities[10]))throw new Exception("unowned task");Drives++;if(DriveFailure)throw new InvalidOperationException("synthetic task invocation failure");}
    public void Brake(Identity r,Identity b,int durationMs){if(!r.Same(Entities[11])||!b.Same(Entities[10])||durationMs<=0||durationMs>20000)throw new Exception("unowned braking");Brakes++;if(BrakeFailure)throw new Exception("braking request failed");}
    public void StopOwnedTask(Identity id){if(Inspect(id)!=Presence.Present)throw new Exception("unowned stop");}
    public void DeleteOwned(Identity id){if(DeleteFailure)throw new Exception("cleanup exception");if(Inspect(id)!=Presence.Present)throw new Exception("unowned delete");Deleted.Add(id.Handle);Entities.Remove(id.Handle);}
}
