        s=new SpeedAnalysis(policy,new MarkerPoint());s.Add(R(dummy,0,0,10),0,0);s.Add(R(dummy,.13,1.235,9),1.235,0);Yes(Math.Abs(s.Summary().LastAcceleration.Value+1/.13)<1e-8&&s.Summary().DeceleratingPairs==1,"irregular time deceleration");
